const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var wuhan = ee.Geometry.Point([114.3055, 30.5928]).buffer(50000); // 50km buffer around Wuhan

  var feb2019 = ee.DateRange('2019-02-01', '2019-02-28');
  var feb2020 = ee.DateRange('2020-02-01', '2020-02-29');

  // 2. Data Acquisition - Sentinel-5P Aerosol Index
  var col2019 = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_AER_AI')
    .filterDate(feb2019)
    .filterBounds(wuhan);

  var col2020 = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_AER_AI')
    .filterDate(feb2020)
    .filterBounds(wuhan);

  // Check collection sizes
  var size2019 = col2019.size().getInfo();
  var size2020 = col2020.size().getInfo();

  console.log(`2019 Images: ${size2019}, 2020 Images: ${size2020}`);

  if (size2019 === 0 || size2020 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Get mean aerosol index (proxy for PM2.5)
  var mean2019 = col2019.mean().select('absorbing_aerosol_index');
  var mean2020 = col2020.mean().select('absorbing_aerosol_index');

  // Count valid pixels
  var count2019 = mean2019.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: wuhan,
    scale: 1000,
    maxPixels: 1e9
  }).get('absorbing_aerosol_index').getInfo();

  var count2020 = mean2020.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: wuhan,
    scale: 1000,
    maxPixels: 1e9
  }).get('absorbing_aerosol_index').getInfo();

  console.log(`Valid pixels 2019: ${count2019}, 2020: ${count2020}`);

  if (count2019 === 0 || count2020 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Get mean values
  var val2019 = mean2019.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: wuhan,
    scale: 1000,
    maxPixels: 1e9
  }).get('absorbing_aerosol_index').getInfo();

  var val2020 = mean2020.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: wuhan,
    scale: 1000,
    maxPixels: 1e9
  }).get('absorbing_aerosol_index').getInfo();

  console.log(`Mean Aerosol Index 2019: ${val2019?.toFixed(3)}`);
  console.log(`Mean Aerosol Index 2020: ${val2020?.toFixed(3)}`);

  // 5. Validation & Final Answer
  if (val2019 === null || val2020 === null || 
      isNaN(val2019) || isNaN(val2020)) {
    console.log("<answer>C3</answer>");
  } else if (val2020 > val2019) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
